"use client";
import type { ComponentProps } from "react";
import { Select as BaseSelect } from "@base-ui/react/select";
import { Icon } from "./icon";
import { haptic } from "./haptics";
import { cn } from "./cn";

export interface SelectProps extends Omit<ComponentProps<typeof BaseSelect.Trigger>, "value" | "onChange" | "className" | "children" | "aria-label" | "disabled" | "placeholder"> {
  value: string;
  onChange: (value: string) => void;
  /** `[value, label]` pairs. */
  options: readonly (readonly [string, string])[];
  /** Accessible name when there is no visible label next to it. */
  label?: string;
  placeholder?: string;
  disabled?: boolean;
  className?: string;
}

/**
 * Drop-down list. A real popup instead of the browser's native one, so it matches the rest of the UI,
 * opens and closes with a spring, and supports type-ahead and arrow keys. Touch opens it below the field.
 */
export function Select({ value, onChange, options, label, placeholder, disabled, className, ...rest }: SelectProps) {
  const items = options.map(([v, l]) => ({ value: v, label: l }));
  return (
    <BaseSelect.Root items={items} value={value} disabled={disabled} onValueChange={(v) => { if (typeof v === "string") { if (v !== value) haptic("select"); onChange(v); } }}>
      <BaseSelect.Trigger data-slot="select" className={cn("sel sel-t", className)} aria-label={label} {...rest}>
        <BaseSelect.Value placeholder={placeholder} />
        <BaseSelect.Icon className="sel-i"><Icon n="chev" c="sm" /></BaseSelect.Icon>
      </BaseSelect.Trigger>
      <BaseSelect.Portal>
        <BaseSelect.Positioner className="pos" sideOffset={6} alignItemWithTrigger={false}>
          <BaseSelect.Popup className="float sel-pop">
            <BaseSelect.List>
              {options.map(([v, l]) => (
                <BaseSelect.Item key={v} value={v} className="sel-item">
                  <BaseSelect.ItemText>{l}</BaseSelect.ItemText>
                  <BaseSelect.ItemIndicator className="sel-check"><Icon n="check" c="sm" /></BaseSelect.ItemIndicator>
                </BaseSelect.Item>
              ))}
            </BaseSelect.List>
          </BaseSelect.Popup>
        </BaseSelect.Positioner>
      </BaseSelect.Portal>
    </BaseSelect.Root>
  );
}

/* Form fields: Field, Input, Textarea, Select. Moved out of globals.css; contextual overrides (.hero .btn, .pg3 .dt) stay with the screens that need them. */
.sel,.inp{min-height:40px;border-radius:12px;border:1.5px solid var(--line);background:var(--tile);padding:0 12px;min-width:0;max-width:100%}
textarea.inp{height:auto;padding:10px 12px;width:100%;resize:vertical}
.sel:focus,.inp:focus{outline:2px solid var(--sage);outline-offset:1px}
.field{display:flex;flex-wrap:wrap;gap:10px;align-items:center;max-width:100%;min-width:0}
.inp--sm{width:84px}
.inp--code{width:140px}
.inp--fill{width:100%}
.inp--mono{font:0.8125rem var(--f-mono);min-width:0}
.time-field{min-width:116px;font-variant-numeric:tabular-nums}
@media(pointer:coarse){.inp,.sel{min-height:44px}}

/* Floating surfaces: Select list, Popover, Tooltip. They live in a portal, so they sit above sheets and dialogs. */
.pos{z-index:80}
.float{background:var(--tile);color:var(--ink);border-radius:16px;box-shadow:0 18px 50px -14px rgba(0,0,0,.45),0 0 0 1px var(--line);outline:0;
  transform-origin:var(--transform-origin,50% 0);transition:transform .4s var(--spring),opacity .16s var(--ease-out)}
.float[data-starting-style],.float[data-ending-style]{opacity:0;transform:scale(.94)}
.float[data-ending-style]{transition:transform .14s var(--ease-in),opacity .12s var(--ease-in)}

.sel-t{display:inline-flex;align-items:center;justify-content:space-between;gap:10px;text-align:left;cursor:pointer;min-width:120px}
.sel-t[data-popup-open]{border-color:var(--sage)}
.sel-t[data-disabled]{opacity:.5;cursor:not-allowed}
.sel-i{display:grid;place-items:center;color:var(--ink3);transform:rotate(90deg);transition:transform .3s var(--spring)}
.sel-t[data-popup-open] .sel-i{transform:rotate(-90deg)}
.sel-pop{min-width:var(--anchor-width);max-height:min(46vh,320px);overflow:auto;padding:6px}
.sel-item{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:9px 12px;border-radius:11px;font-weight:600;font-size:0.875rem;cursor:pointer;user-select:none;outline:0}
.sel-item[data-highlighted]{background:var(--tile2)}
.sel-item[data-selected]{color:var(--sage-ink)}
.sel-check{display:grid;place-items:center}

.pop{padding:14px;min-width:200px;max-width:min(320px,calc(100vw - 32px));display:flex;flex-direction:column;gap:8px}
.pop-t{font:650 1rem var(--f-display);font-stretch:92%;margin:0}

.tip{background:var(--ink);color:var(--tile);font-size:0.7812rem;font-weight:600;padding:6px 10px;border-radius:10px;box-shadow:0 8px 24px -8px rgba(0,0,0,.5);
  transform-origin:var(--transform-origin,50% 100%);transition:transform .25s var(--spring),opacity .12s var(--ease-out);pointer-events:none}
.tip[data-starting-style],.tip[data-ending-style]{opacity:0;transform:scale(.92)}
.tip[data-instant]{transition-duration:0s}

@media (prefers-reduced-motion:reduce){
  .float,.tip{transition:opacity .12s linear}
  .float[data-starting-style],.float[data-ending-style],.tip[data-starting-style],.tip[data-ending-style]{transform:none}
  .sel-i{transition:none}
}
